<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/bootstrap.php';require_method('POST');$u=require_role('OWNER','ADMIN');require_csrf();$d=input();$id=string_value($d,'id',36);$recipient=email_value($d,'testEmail');$enableAfterTest=filter_var($d['enableAfterTest']??true,FILTER_VALIDATE_BOOL);rate_limit('smtp_test',$u['tenant_id'].':'.$u['id'],10,3600);$s=db()->prepare('SELECT * FROM smtp_accounts WHERE tenant_id=? AND public_id=? LIMIT 1');$s->execute([$u['tenant_id'],$id]);$a=$s->fetch();if(!$a)throw new ApiError(404,'SMTP account not found.');assert_safe_smtp_host($a['host']);db()->prepare("UPDATE smtp_accounts SET status='TESTING',is_active=0,last_error=NULL WHERE id=? AND tenant_id=?")->execute([$a['id'],$u['tenant_id']]);
try{MailService::testCustomerAccount(['host'=>$a['host'],'port'=>$a['port'],'encryption'=>$a['encryption'],'username'=>$a['username'],'password'=>decrypt_secret($a['password_ciphertext']),'sender_email'=>$a['sender_email'],'sender_name'=>$a['sender_name']],$recipient);db()->prepare("UPDATE smtp_accounts SET status='CONNECTED',is_active=?,last_tested_at=UTC_TIMESTAMP(),last_error=NULL WHERE id=? AND tenant_id=?")->execute([$enableAfterTest?1:0,$a['id'],$u['tenant_id']]);audit('smtp.test_succeeded','smtp_account',$id,['testRecipient'=>$recipient,'enabled'=>$enableAfterTest]);respond(['status'=>'CONNECTED','isActive'=>$enableAfterTest,'message'=>'Branded test email sent successfully.']);}
catch(Throwable $e){$safe=mb_substr(preg_replace('/(password|auth|credential)[^\s]*/i','[redacted]',$e->getMessage())??'Connection failed',0,500);db()->prepare("UPDATE smtp_accounts SET status='ERROR',is_active=0,last_tested_at=UTC_TIMESTAMP(),last_error=? WHERE id=? AND tenant_id=?")->execute([$safe,$a['id'],$u['tenant_id']]);audit('smtp.test_failed','smtp_account',$id,['error'=>$safe]);throw new ApiError(422,'SMTP test failed. Sending has been blocked until the account passes a new test.',['diagnostic'=>$safe]);}
